<template><div class="admin-applications-page"><AdminApplicationsTabs active="reviewers"/><DemoIdentitySwitcher/><div v-if="identity.role!=='admin'" class="applications-queue applications-state"><strong>Admin demo view required</strong><p>Reviewer performance and organisation-wide comparisons are restricted to authorised admins.</p></div><template v-else><header class="applications-page-header"><div><h1>Reviewer performance</h1><p>Quality-assurance and calibration signals for fictional Creator Programme reviews. Differences are not evidence of misconduct.</p></div><span class="demo-data-badge">Demo analytics</span></header><p class="calibration-setting">Demo calibration setting: at least <strong>{{settings.minimumComparableReviews}} comparable completed reviews</strong>. This threshold requires future policy approval.</p><form class="review-dashboard-filters" @submit.prevent><label><span>From date</span><input v-model="filters.from" type="date"/></label><label><span>To date</span><input v-model="filters.to" type="date"/></label><label><span>Pathway</span><select v-model="filters.pathway"><option value="">All pathways</option><option value="creator">Creator Programme</option></select></label><label><span>Rubric version</span><select v-model="filters.rubricVersion"><option value="">All rubric versions</option><option value="creator-demo-v1">Creator demo v1</option></select></label><label><span>Review provenance</span><select v-model="filters.provenance"><option value="">All provenance</option><option>Independent review</option><option>Independent admin review</option><option>Informed admin review</option></select></label><label><span>Minimum sample</span><input v-model.number="filters.minimumSample" type="number" min="0"/></label></form><div class="applications-table-scroll applications-queue"><table class="applications-table reviewer-performance-table"><thead><tr><th>Reviewer</th><th>Activity</th><th>Scores</th><th>Threshold rates</th><th>Quality indicators</th><th>Completion</th><th>Peer comparison</th><th>Calibration</th><th>Action</th></tr></thead><tbody><tr v-for="r in metrics" :key="r.reviewerId"><td><strong>{{r.reviewerName}}</strong><small>{{r.reviewerStatus}} · sample {{r.sampleSize}}</small></td><td>{{r.claimed}} claimed · {{r.started}} started · {{r.completed}} completed<small>{{r.released}} released</small></td><td>Avg {{pct(r.average)}} · median {{pct(r.median)}}<small>High {{pct(r.highest)}} · low {{pct(r.lowest)}}</small></td><td>≥85: {{pct(r.atLeast85)}}<small>&lt;35: {{pct(r.below35)}}</small></td><td>Concern {{pct(r.concernRate)}} · clarification {{pct(r.clarificationRate)}}<small>Comment coverage {{pct(r.commentCoverage)}}</small></td><td>{{r.averageCompletionHours}} hours average</td><td>{{difference(r.averagePeerDifference)}}<small>{{r.averageAbsoluteDifference}} pp average absolute · {{r.materialDisagreement}} material</small></td><td><span class="calibration-badge">{{r.calibrationStatus}}</span></td><td><RouterLink :to="{name:'AdminReviewerDetail',params:{reviewerId:r.reviewerId}}">Inspect details</RouterLink></td></tr></tbody></table></div><div class="reviewer-mobile-cards"><article v-for="r in metrics" :key="r.reviewerId" class="application-panel"><h2>{{r.reviewerName}}</h2><dl class="metadata-list"><div><dt>Sample</dt><dd>{{r.sampleSize}}</dd></div><div><dt>Average / median</dt><dd>{{pct(r.average)}} / {{pct(r.median)}}</dd></div><div><dt>Peer difference</dt><dd>{{difference(r.averagePeerDifference)}}</dd></div><div><dt>Comment coverage</dt><dd>{{pct(r.commentCoverage)}}</dd></div><div><dt>Calibration</dt><dd>{{r.calibrationStatus}}</dd></div></dl><RouterLink :to="{name:'AdminReviewerDetail',params:{reviewerId:r.reviewerId}}">Inspect reviewer details</RouterLink></article></div></template></div></template>
<script>import AdminApplicationsTabs from'./components/AdminApplicationsTabs.vue';import DemoIdentitySwitcher from'./components/DemoIdentitySwitcher.vue';import{demoWorkflow,getDemoIdentity}from'./applicationAdminData.js';import{DEMO_CALIBRATION_SETTINGS,reviewerDashboard}from'./reviewerPerformanceData.js';export default{name:'AdminReviewerPerformance',components:{AdminApplicationsTabs,DemoIdentitySwitcher},data:()=>({workflow:demoWorkflow,settings:DEMO_CALIBRATION_SETTINGS,filters:{from:'',to:'',pathway:'creator',rubricVersion:'creator-demo-v1',provenance:'',minimumSample:0}}),computed:{identity(){this.workflow.revision;return getDemoIdentity()},metrics(){return this.identity.role==='admin'?reviewerDashboard(this.filters):[]}},methods:{pct(v){return v===null?'—':`${v}%`},difference(v){if(v===null)return'Limited evidence';if(Math.abs(v)<=3)return`Within ${Math.abs(v)} percentage points of peers`;return`${v>0?'+':''}${v} percentage points ${v>0?'above':'below'} peers`}}};</script><style src="./AdminApplications.css"></style>
